// 不要改动版本号,影响更新
const LOCAL_VERSION = "4.1";

var hosts = [
    "https://read.search.qingread.icu",
    "http://154.64.253.94:8887",
    "https://search.qingread.icu",
    "http://searchs.qingread.icu:6789"
];

//书源配置列表
var sourceList = [
    {n:"sou1", v:null, m:"☁️聚合搜索"},
    {n:"sou2", v:"霹雳书坊", m:"霹雳书坊"},
    {n:"sou3", v:"星星", g:"boy", m:"星星小说"},
    {n:"sou4", v:"久久", m:"久久小说"},
    {n:"sou5", v:"二三小说", m:"二三小说"},
